INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'coulomb-law', 'กฎของคูลอมบ์: แรงระหว่างประจุไฟฟ้า', 'แรงระหว่างประจุจุดสองประจุแปรผันตามผลคูณของขนาดประจุ และแปรผกผันกับกำลังสองของระยะห่าง', 'senior', 1, 'published');
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'coulomb-law'), 'youtube', 'https://www.youtube.com/watch?v=u0nVk4FLAz8', 'u0nVk4FLAz8', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.2 (แรงไฟฟ้าและกฎของคูลอมบ์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'coulomb-law'), 'coulomb', 'ปรับประจุและระยะห่าง แล้วดูแรง', '{}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'coulomb-law'), 'แบบทดสอบ: กฎของคูลอมบ์', 60);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'choice', 'ถ้าระยะห่างระหว่างประจุสองประจุเพิ่มขึ้นเป็น 2 เท่า แรงระหว่างประจุเปลี่ยนเป็นกี่เท่าของเดิม', '["2 เท่า","1/2 เท่า","4 เท่า","1/4 เท่า"]', '3', 'แรงแปรผกผันกับกำลังสองของระยะห่าง F ∝ 1/r² เมื่อ r เป็น 2 เท่า F จึงเป็น 1/4 เท่า', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'choice', 'ประจุ +2 ไมโครคูลอมบ์ กับ −3 ไมโครคูลอมบ์ วางห่างกัน แรงระหว่างประจุเป็นแบบใด', '["ผลักกัน","ดึงดูดกัน","ไม่มีแรง","ผลักกันที่ระยะใกล้ ดึงดูดที่ระยะไกล"]', '1', 'ประจุต่างชนิดกันดึงดูดกัน ประจุชนิดเดียวกันผลักกัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'number', 'ประจุ 2 ไมโครคูลอมบ์ สองประจุ วางห่างกัน 0.3 เมตร ในสุญญากาศ แรงระหว่างประจุมีขนาดกี่นิวตัน (ใช้ k = 9 × 10⁹ นิวตัน·เมตร²/คูลอมบ์²)', NULL, '{"value":0.4,"tolerance":0.01}', 'F = k q1 q2 / r² = 9×10⁹ × (2×10⁻⁶)² / 0.3² = 0.036 / 0.09 = 0.4 นิวตัน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'choice', 'ถ้าเพิ่มประจุตัวหนึ่งเป็น 3 เท่า โดยระยะห่างเท่าเดิม แรงระหว่างประจุเป็นกี่เท่าของเดิม', '["3 เท่า","9 เท่า","1/3 เท่า","เท่าเดิม"]', '0', 'แรงแปรผันตรงกับผลคูณของประจุ F ∝ q1 q2 เมื่อประจุหนึ่งเป็น 3 เท่า แรงจึงเป็น 3 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'choice', 'แรงที่ประจุ A กระทำต่อประจุ B กับแรงที่ B กระทำต่อ A มีความสัมพันธ์กันอย่างไร', '["ขนาดไม่เท่ากัน","ขนาดเท่ากัน ทิศตรงข้ามกัน","ขนาดเท่ากัน ทิศเดียวกัน","ขึ้นกับขนาดของประจุที่มากกว่า"]', '1', 'เป็นแรงคู่กิริยา-ปฏิกิริยาตามกฎข้อที่ 3 ของนิวตัน ขนาดเท่ากันและทิศตรงข้าม', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'reflection-refraction'), 'light-reflection', 'การสะท้อนของแสง: กฎการสะท้อน', 'แสงสะท้อนจากผิวเรียบโดยมุมตกกระทบเท่ากับมุมสะท้อน และรังสีทั้งสองอยู่ในระนาบเดียวกับเส้นปกติ', 'senior', 1, 'published');
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'light-reflection'), 'youtube', 'https://www.youtube.com/watch?v=OWvMKjP-d1s', 'OWvMKjP-d1s', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.1 (สมบัติของแสง,การสะท้อนของแสง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'light-reflection'), 'reflection', 'ปรับมุมตกกระทบ แล้วดูมุมสะท้อน', '{}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'light-reflection'), 'แบบทดสอบ: การสะท้อนของแสง', 60);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'choice', 'กฎการสะท้อนของแสงกล่าวว่าอย่างไร', '["มุมตกกระทบเท่ากับมุมสะท้อน","มุมตกกระทบมากกว่ามุมสะท้อน","มุมตกกระทบน้อยกว่ามุมสะท้อน","มุมสะท้อนเป็น 90 องศาเสมอ"]', '0', 'กฎการสะท้อน: มุมตกกระทบเท่ากับมุมสะท้อน และรังสีตกกระทบ รังสีสะท้อน กับเส้นปกติอยู่ในระนาบเดียวกัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'number', 'แสงตกกระทบกระจกเงาระนาบด้วยมุมตกกระทบ 35 องศา มุมสะท้อนเท่ากับกี่องศา', NULL, '{"value":35,"tolerance":0.5}', 'มุมสะท้อนเท่ากับมุมตกกระทบ จึงเป็น 35 องศา', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'choice', 'มุมตกกระทบวัดจากเส้นใด', '["ผิวของกระจก","เส้นปกติ ซึ่งตั้งฉากกับผิวกระจก","แนวระดับ","รังสีสะท้อน"]', '1', 'มุมตกกระทบและมุมสะท้อนวัดจากเส้นปกติ ไม่ได้วัดจากผิวกระจก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'number', 'รังสีแสงตกกระทบกระจกเงาระนาบทำมุม 30 องศากับผิวกระจก มุมสะท้อนมีค่ากี่องศา (วัดจากเส้นปกติ)', NULL, '{"value":60,"tolerance":0.5}', 'มุมที่ทำกับผิวกระจกคือ 30 องศา จึงทำมุม 90 − 30 = 60 องศากับเส้นปกติ มุมตกกระทบจึงเป็น 60 องศา และมุมสะท้อนเท่ากับ 60 องศา', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'choice', 'เมื่อแสงตกตั้งฉากกับกระจกเงาระนาบ (มุมตกกระทบ 0 องศา) รังสีสะท้อนเป็นอย่างไร', '["สะท้อนกลับตามแนวเดิม","สะท้อนทำมุม 90 องศา","ทะลุผ่านกระจก","หายไป"]', '0', 'มุมตกกระทบ 0 องศา มุมสะท้อนจึงเป็น 0 องศาด้วย รังสีสะท้อนกลับไปตามแนวเดิม', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'projectile'), 'projectile-intro', 'โพรเจกไทล์: ภาพรวมการเคลื่อนที่เป็นเส้นโค้ง', 'วัตถุที่ถูกยิงเฉียงขึ้นเคลื่อนที่เป็นเส้นโค้งพาราโบลา เพราะในแนวราบความเร็วคงที่ ส่วนในแนวตั้งมีความเร่งจากแรงโน้มถ่วง', 'senior', 1, 'published');
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-intro'), 'projectile', 'ลองยิงวัตถุเฉียงขึ้น', '{"angle":{"min":10,"max":80,"default":45},"speed":{"min":10,"max":40,"default":25}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-intro'), 'aim-and-shoot', 'ยิงให้ถูกเป้า', '{"targetDistance":[40,120],"tolerance":3}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-intro'), 'แบบทดสอบ: โพรเจกไทล์', 60);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'choice', 'ในการเคลื่อนที่แบบโพรเจกไทล์ (ไม่คิดแรงต้านอากาศ) ความเร็วในแนวราบเปลี่ยนแปลงอย่างไร', '["เพิ่มขึ้นเรื่อยๆ","ลดลงเรื่อยๆ","คงที่","เป็นศูนย์ที่จุดสูงสุด"]', '2', 'ในแนวราบไม่มีแรงกระทำ (เมื่อไม่คิดแรงต้านอากาศ) ความเร่งแนวราบจึงเป็นศูนย์ ความเร็วแนวราบคงที่ตลอดการเคลื่อนที่', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'choice', 'ที่จุดสูงสุดของวิถี ความเร็วในแนวตั้งมีค่าเท่าใด', '["เท่ากับความเร็วต้นในแนวตั้ง","เป็นศูนย์","เท่ากับ g","มากที่สุด"]', '1', 'ที่จุดสูงสุดวัตถุเปลี่ยนจากขึ้นเป็นลง ความเร็วแนวตั้งจึงเป็นศูนย์ แต่ความเร็วแนวราบยังมีอยู่ และความเร่งยังเท่ากับ g ในทิศลง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'choice', 'ถ้าความเร็วต้นเท่ากัน และไม่คิดแรงต้านอากาศ มุมยิงใดทำให้ระยะทางในแนวราบไกลที่สุด', '["30 องศา","45 องศา","60 องศา","90 องศา"]', '1', 'ระยะทางแนวราบ R = v² sin 2θ / g และ sin 2θ มีค่ามากที่สุดเมื่อ 2θ = 90 องศา คือ θ = 45 องศา', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'number', 'ยิงวัตถุด้วยความเร็วต้น 20 เมตร/วินาที ที่มุม 30 องศากับแนวราบ วัตถุอยู่ในอากาศนานกี่วินาที (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":2,"tolerance":0.05}', 'เวลาที่ลอย T = 2v sin θ / g = 2 × 20 × 0.5 / 10 = 2 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'number', 'จากข้อก่อนหน้า วัตถุตกห่างจุดยิงในแนวราบกี่เมตร (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":34.6,"tolerance":0.5}', 'R = v cos θ × T = 20 × 0.866 × 2 ≈ 34.6 เมตร (หรือใช้ R = v² sin 2θ / g = 400 × 0.866 / 10)', 5);
